  assertNotArchived(\"Issue\", issue.id, issue);
  assertNotArchived(\"Issue\", blocker.id, blocker);
  if (issue.id === blocker.id) throw new Error(\"An issue cannot block itself\");
  const links = await dependencyRepo.listDependencies(input.orgId);
  const existing = links.find((link) => link.issueId === issue.id && link.blockerId === blocker.id);
  if (existing) return existing;
  const pending: IssueId[] = [blocker.id];
  const visited = new Set<IssueId>();
  while (pending.length) {
    const id = pending.pop()"'!;
    if (id === issue.id) throw new Error("Issue dependency would create a cycle");
    if (visited.has(id)) continue;
    visited.add(id);
    for (const link of links) if (link.issueId === id) pending.push(link.blockerId);
  }
  return dependencyRepo.insertDependency(input.orgId, issue.id, blocker.id, actor.userId);
