import { subscribe } from \"@/lib/event-bus\";
import * as dependencyRepo from \"@/server/repositories/issue-dependency-repository\";
import * as issueRepo from \"@/server/repositories/issue-repository\";
import { getBlockers, isOpen } from \"./issue-dependency-service\";
import { notify } from \"./notification-service\";
import type { IssueId, OrgId, UserId } from \"@/types/common\";
import type { IssueStatus } from \"@/types/issue\";
import type { Unsubscribe } from \"@/types/event\";

function closed(status: IssueStatus): boolean {
  return status === \"done\" || status === \"canceled\";
}

async function notifyUnblocked(orgId: OrgId, blockerId: IssueId, actorId: UserId | null): Promise<void> {
  const links = (await dependencyRepo.listDependencies(orgId)).filter((link) => link.blockerId === blockerId);
  for (const link of links) {
    const issue = await issueRepo.findIssueById(orgId, link.issueId);
    if ("'!issue || !isOpen(issue) || !issue.assigneeId) continue;
    if ((await getBlockers(orgId, issue.id)).some(isOpen)) continue;
    await notify(orgId, "issue_unblocked", [issue.assigneeId], {
      title: "Issue unblocked", body: `Issue ${issue.id} is now unblocked`,
      href: `/issues/${issue.id}`, actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offStatus = subscribe("issue.status_changed", async (event) => {
    if (!closed(event.from) && closed(event.to)) await notifyUnblocked(event.orgId, event.issueId, event.actorId);
  });
  const offArchive = subscribe("issue.archived", async (event) => {
    const issue = await issueRepo.findIssueById(event.orgId, event.issueId);
    if (issue && !closed(issue.status)) await notifyUnblocked(event.orgId, event.issueId, event.actorId);
  });
  return () => { offStatus(); offArchive(); };
}
